import { tokenize, tokenTypes } from "css-tree";

/**
 * Extracts the upstream notice without reprinting its tokens.
 *
 * @param css - CSS generated by the installed Tailwind compiler.
 * @param version - Installed package version that the notice must identify.
 * @returns The complete original important comment, excluding surrounding whitespace.
 * @throws If the output does not contain exactly one matching notice.
 */
export function extractTailwindBanner(css: string, version: string): string {
  const comments: string[] = [];
  tokenize(css, (type, start, end) => {
    const text = css.slice(start, end);
    if (type === tokenTypes.Comment && text.startsWith("/*!") && /\btailwindcss\b/.test(text)) {
      comments.push(text);
    }
  });
  if (comments.length !== 1 || !comments[0].includes(`tailwindcss v${version} |`)) {
    throw new Error(`Cannot uniquely extract the Tailwind ${version} banner`);
  }
  return comments[0];
}

/**
 * Quotes UTF-8 text as a Rust string literal without changing its decoded content.
 *
 * @param text - Original comment text.
 * @returns A quoted Rust string literal.
 */
export function rustString(text: string): string {
  const escaped = Array.from(text, (char) => {
    if (char === '"' || char === "\\") {
      return `\\${char}`;
    }
    const code = char.codePointAt(0)!;
    return code < 0x20 || code === 0x7f ? `\\u{${code.toString(16)}}` : char;
  }).join("");
  return `"${escaped}"`;
}
